var LC_MODELS = [
  { id:'gpt-4o',            label:'GPT-4o',              inp:2.50,  out:10.00, ctx:128000 },
  { id:'gpt-4o-mini',       label:'GPT-4o mini',         inp:0.15,  out:0.60,  ctx:128000 },
  { id:'o3-mini',           label:'o3-mini',             inp:1.10,  out:4.40,  ctx:200000 },
  { id:'claude-sonnet',     label:'Claude Sonnet',       inp:3.00,  out:15.00, ctx:200000 },
  { id:'claude-haiku',      label:'Claude Haiku',        inp:0.80,  out:4.00,  ctx:200000 },
  { id:'gemini-flash',      label:'Gemini Flash',        inp:0.075, out:0.30,  ctx:1000000 },
  { id:'gemini-pro',        label:'Gemini Pro',          inp:1.25,  out:5.00,  ctx:2000000 },
  { id:'deepseek-chat',     label:'DeepSeek Chat',       inp:0.27,  out:1.10,  ctx:64000 },
  { id:'qwen-max',          label:'Qwen Max',            inp:1.60,  out:6.40,  ctx:32000 },
  { id:'local-0',           label:'本地部署（自托管）',    inp:0,     out:0,     ctx:32000 }
];
function lcFindModel(id){
  for(var i=0;i<LC_MODELS.length;i++) if(LC_MODELS[i].id===id) return LC_MODELS[i];
  return null;
}
function lcEstimateTokens(text){
  var s=String(text||'');
  if(!s) return 0;
  var cjk=(s.match(/[\u4e00-\u9fa5\u3040-\u30ff\uac00-\ud7af]/g)||[]).length;
  var rest=s.length-cjk;
  return Math.max(1, Math.round(cjk*0.95 + rest/3.8));
}
function lcCost(model, inTok, outTok){
  if(!model) return null;
  var i=(inTok||0)/1e6*model.inp, o=(outTok||0)/1e6*model.out;
  return { input:i, output:o, total:i+o };
}
function lcRound(v, digits){
  var d=Math.pow(10, digits===undefined?6:digits);
  return Math.round(v*d)/d;
}
function lcFmtUsd(v){
  if(v===0) return '$0';
  if(v<0.01) return '$'+v.toFixed(6);
  if(v<1) return '$'+v.toFixed(4);
  return '$'+v.toFixed(2);
}
function lcProject(model, inTok, outTok, callsPerDay, cnyRate){
  var c=lcCost(model, inTok, outTok);
  if(!c) return null;
  var rate = cnyRate || 7.2;
  var per=c.total, day=per*(callsPerDay||0), mon=day*30, yr=day*365;
  return { per:per, day:day, month:mon, year:yr,
           monthCny:mon*rate, yearCny:yr*rate };
}
function lcCompare(inTok, outTok, callsPerDay){
  var out=[];
  for(var i=0;i<LC_MODELS.length;i++){
    var m=LC_MODELS[i], c=lcCost(m, inTok, outTok);
    out.push({ id:m.id, label:m.label, per:c.total, month:c.total*(callsPerDay||0)*30,
               fits:(inTok+outTok)<=m.ctx });
  }
  out.sort(function(a,b){ return a.per-b.per || (a.id<b.id?-1:1); });
  return out;
}
function lcCacheSaving(model, inTok, outTok, hitRate, discount){
  var base=lcCost(model, inTok, outTok);
  if(!base) return null;
  var d = discount===undefined ? 0.9 : discount;
  var h = Math.max(0, Math.min(1, hitRate||0));
  var saved = base.input * h * d;
  return { base:base.total, cached:base.total-saved, saved:saved,
           pct: base.total ? saved/base.total : 0 };
}
function lcCtxWarn(model, inTok, outTok){
  if(!model) return null;
  var used=(inTok||0)+(outTok||0);
  var ratio=used/model.ctx;
  if(ratio>1) return { level:'错误', msg:'超出上下文窗口（'+used+' > '+model.ctx+'）' };
  if(ratio>0.8) return { level:'警告', msg:'已用 '+(ratio*100).toFixed(1)+'% 上下文窗口，接近上限' };
  return { level:'正常', msg:'占用 '+(ratio*100).toFixed(1)+'% 上下文窗口' };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { LC_MODELS:LC_MODELS, lcFindModel:lcFindModel, lcEstimateTokens:lcEstimateTokens,
    lcCost:lcCost, lcRound:lcRound, lcFmtUsd:lcFmtUsd, lcProject:lcProject, lcCompare:lcCompare,
    lcCacheSaving:lcCacheSaving, lcCtxWarn:lcCtxWarn };
}
if (typeof window !== 'undefined') {
  window.LlmCostForgePure = { LC_MODELS:LC_MODELS, lcFindModel:lcFindModel, lcEstimateTokens:lcEstimateTokens,
    lcCost:lcCost, lcRound:lcRound, lcFmtUsd:lcFmtUsd, lcProject:lcProject, lcCompare:lcCompare,
    lcCacheSaving:lcCacheSaving, lcCtxWarn:lcCtxWarn };
}
